function makeChecker(limit) {
  return (n) => n > limit;
}

function countPassing(values, check) {
  const limit = 1000;

  return values.filter(check).length;
}

const scores = [40, 55, 70, 90];

console.log(countPassing(scores, makeChecker(50)));
console.log(countPassing(scores, makeChecker(80)));
console.log(countPassing(scores, (n) => n > scores.length));
